    input reset,
    output reg [15:0] led = 0
    );

code:
module top_module(
    input clk,
    input reset,
    output reg [15:0] led = 0
    );integer flash_delay = 0;
    always @(posedge clk, posedge reset) begin
        if(reset) begin
            flash_delay <= 0;
            led <= 0;
        end
        else begin 
            if(flash_delay >= 3) begin 
                flash_delay <= 0;
                led <= ~led;
            end
            else begin
                flash_delay <= flash_delay + 1; 
            end
        end
    end
endmodule

