description:
Design a Moore state machine that operates with four distinct states, generating a two-bit output based on the current state. The output signals are defined such that in state 0 the output is "00," in state 1 it is "01," in state 2 it is "10," and in state 3 it is "11." The state transitions occur on the rising edge of the clock signal, returning to state 0 after reaching state 3, while providing the capability to reset to state 0 asynchronously.
module top_module(
  input clk,
  input rst,
  output [m-1:0] out
);

code:
module top_module(
  input clk,
  input rst,
  output [m-1:0] out
);parameter n = 4; // number of states
parameter m = 2; // number of output signals

reg [n-1:0] state;
reg [m-1:0] out_reg;

// Define the output signals as functions of the current state
always @ (state) begin
  case (state)
    0: out_reg = {1'b0, 1'b0};
    1: out_reg = {1'b0, 1'b1};
    2: out_reg = {1'b1, 1'b0};
    3: out_reg = {1'b1, 1'b1};
  endcase
end

// Define the state transitions
always @ (posedge clk, posedge rst) begin
  if (rst) begin
    state <= 0;
  end else begin
    case (state)
      0: state <= 1;
      1: state <= 2;
      2: state <= 3;
      3: state <= 0;
    endcase
  end
end

// Assign the output signals
assign out = out_reg;

endmodule

