module top_module(
    input Clock, Reset, DataInValid,
    input [7:0] DataIn,
    output SOut, DataInReady
);parameter ClockFreq = 50_000_000;
parameter Baud = 9600;
parameter Width = 8;
parameter Parity = 0;
parameter StopBits = 1;

localparam Divisor = ClockFreq / Baud;
localparam BitCount = Width + Parity + StopBits + 1;
localparam Capture = Divisor / 2;
localparam BCWidth = $clog2(BitCount + 1);
localparam DivWidth = $clog2(Divisor); // Added DivWidth definition

reg [BCWidth-1:0] TxBitCount;
reg [DivWidth-1:0] TxDivCount;
reg [BitCount-1:0] TxData;
reg TxShiftEnable, TxRunning, TxStart, TxParity;
reg [BitCount-1:0] DataInAugmented; // Adjusted width to 'BitCount'

assign DataInReady = ~TxRunning & ~Reset;

always @(*) begin
    TxShiftEnable = (TxDivCount == (Divisor - 1));
    TxRunning = (TxBitCount < BitCount);
    TxStart = DataInValid & DataInReady;
end

always @(*) begin
    DataInAugmented = Parity ? {{StopBits{1'b1}}, TxParity, DataIn, 1'b0} : {{StopBits{1'b1}}, DataIn, 1'b0};
end

always @(posedge Clock) begin
    if (Reset) begin
        TxDivCount <= 0;
        TxBitCount <= 0;
        TxData <= {BitCount{1'b1}};
        TxShiftEnable <= 0;
        TxRunning <= 0;
        TxStart <= 0;
        TxParity <= 0;
    end
    else begin
        if (TxStart) begin
            TxDivCount <= 0;
            TxBitCount <= 0;
            TxData <= {1'b0, DataInAugmented, 1'b1};
            TxShiftEnable <= 0;
            TxRunning <= 1;
            TxParity <= Parity ? ^DataIn : 1'b0;
        end
        else if (TxShiftEnable) begin
            TxDivCount <= 0;
            TxBitCount <= TxBitCount + 1;
            TxData <= {TxData[BitCount-2:0], 1'b0};
            TxShiftEnable <= 1;
            TxRunning <= (TxBitCount != BitCount-1);
        end
        else begin
            TxDivCount <= TxDivCount + 1;
            TxBitCount <= TxBitCount;
            TxData <= TxData;
            TxShiftEnable <= 0; // This line should not change in this context
            TxRunning <= 1; // This line should not change in this context
        end
    end
end

assign SOut = TxData[BitCount-1];

endmodule

