  input [7:0] x_0a,
  output reg x_0r,
  output reg [7:0] x_0d,
  input [7:0] y_0a,
  output reg y_0r,
  output reg [7:0] y_0d,
  output reg z_0a,
  input z_0r,
  output reg [7:0] z_0d
);reg [8:0] y_reg;
  reg [7:0] x_reg;
  reg [7:0] z_reg;
  reg [3:0] counter;

  always @(*) begin
    x_0r = x_0a[0];
    y_0r = y_0a[0];
    z_0d = z_reg;
    z_0a = 1;
  end

  always @(posedge z_0r) begin
    if (z_0r) begin
      z_reg <= z_0d;
    end
  end

  always @(posedge z_0r or posedge activate_0r) begin
    if (activate_0r && z_0r) begin
      x_reg <= x_0d;
      y_reg <= {1'b0, y_0d};
      counter <= 4;
    end
  end

  always @(posedge z_0r) begin
    if (counter > 0) begin
      if (y_reg[0] && !y_reg[1]) begin
        z_reg <= z_reg - x_reg;
      end else if (!y_reg[0] && y_reg[1]) begin
        z_reg <= z_reg + x_reg;
      end
      y_reg <= {y_reg[8], y_reg[7:1]};
      counter <= counter - 1;
    end
  end

  always @(posedge z_0r) begin
    if (counter == 0) begin
      z_0d <= z_reg;
    end
  end

endmodule

module top_module(	input clk,
	input rst,

	input left,
	input right,
	input up,
	input down,

	output reg[7:0] direction
);reg [31:0]clk_cnt;
	reg left_key_last;
	reg right_key_last;
	reg up_key_last;
	reg down_key_last;

	always@(posedge clk or negedge rst) begin
		if(!rst) begin
			clk_cnt <= 0;
			direction <= 8'b0;

			left_key_last <= 0;
			right_key_last <= 0;
			up_key_last <= 0;
			down_key_last <= 0;					
		end	
		else begin
			if(clk_cnt == 5_0000) begin
				clk_cnt <= 0;
				left_key_last <= left;
				right_key_last <= right;
				up_key_last <= up;
				down_key_last <= down;

				if(left_key_last == 0 && left == 1) 
					direction <= 8'b0000_0001;
				if(right_key_last == 0 && right == 1)
					direction <= 8'b0000_0010;
				if(up_key_last == 0 && up == 1)
					direction <= 8'b0000_0011;
				if(down_key_last == 0 && down == 1)
					direction <= 8'b0000_0100;
			end						
			else begin
				clk_cnt <= clk_cnt + 1;
				direction <= 8'b0000_0000;
			end
		end	
	end				
endmodule

