            q <= 0;
            q_bar <= 1;
        end else if (set) begin
            q <= 1;
            q_bar <= 0;
        end else if (reset) begin
            q <= 0;
            q_bar <= 1;
        end else begin
            q <= d;
            q_bar <= ~d;
        end
    end

endmodule

