module fsm_module (
        input clk,
        input reset,
        input in,
        output reg out);parameter S0=0, S1=1, S2=2, S3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= S0;
		else state <= next;


	always_comb begin
		case (state)
			S0: next = in ? S1 : S0;
			S1: next = in ? S2 : S1;
			S2: next = in ? S3 : S2;
			S3: next = in ? S0 : S3;
			default: next = 'x;
		endcase
	end

	assign out = (state == S2) || (state == S3);

endmodule

