module top_module(
			input negedge_clk,
			input posedge_clk,
			input rx_resetn,

			input rx_din,

			output reg bit_c_0,
			output reg bit_c_1,
			output reg bit_c_2,
			output reg bit_c_3
		  );always@(posedge posedge_clk or negedge rx_resetn)
