module top_module(
	input [7:0] A,
	input [7:0] B,
	input [1:0] op,
	output [7:0] S,
	output [7:0] D,
	output [7:0] P,
	output [7:0] Q
);reg [8:0] temp_result;

	always @(*) begin
		case(op)
			2'b00: temp_result = A + B;
			2'b01: temp_result = A - B;
			2'b10: temp_result = A * B;
			2'b11: temp_result = A / B;
		endcase
	end

	assign S = (temp_result > 8'hFF) ? 8'hFF : temp_result;
	assign D = (temp_result < 0) ? 0 : temp_result;
	assign P = (temp_result > 8'hFF) ? 8'hFF : temp_result;
	assign Q = (B == 0) ? 8'hFF : A / B;

endmodule

