module top_module(
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] sum,
    output overflow
);// Internal wire declaration
    wire [3:0] carry;

    // Ripple carry adder implementation
    assign carry[0] = 1'b0;
    assign sum[0] = a[0] ^ b[0] ^ carry[0];
    assign carry[1] = (a[0] & b[0]) | (a[0] & carry[0]) | (b[0] & carry[0]);
    assign sum[1] = a[1] ^ b[1] ^ carry[1];
    assign carry[2] = (a[1] & b[1]) | (a[1] & carry[1]) | (b[1] & carry[1]);
    assign sum[2] = a[2] ^ b[2] ^ carry[2];
    assign carry[3] = (a[2] & b[2]) | (a[2] & carry[2]) | (b[2] & carry[2]);
    assign sum[3] = a[3] ^ b[3] ^ carry[3];

    // Overflow detection
    assign overflow = carry[3];

endmodule

module top_module(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);// Define the states for the state machine
  parameter IDLE = 2'b00;
  parameter RISING_EDGE = 2'b01;
  parameter FALLING_EDGE = 2'b10;

  // Define the current state and next state variables
  reg [1:0] current_state, next_state;

  // Initialize the current state to IDLE
  initial current_state = IDLE;

  // Detect rising and falling edges
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      current_state <= IDLE;
      rise <= 1'b0;
      down <= 1'b0;
    end
    else begin
      current_state <= next_state;
      case (current_state)
        IDLE: begin
          if (a == 1'b1) begin
            next_state = RISING_EDGE;
          end
          else if (a == 1'b0) begin
            next_state = FALLING_EDGE;
          end
          else begin
            next_state = IDLE;
          end
          rise <= 1'b0;
          down <= 1'b0;
        end
        RISING_EDGE: begin
          next_state = IDLE;
          rise <= 1'b1;
          down <= 1'b0;
        end
        FALLING_EDGE: begin
          next_state = IDLE;
          rise <= 1'b0;
          down <= 1'b1;
        end
        default: begin
          next_state = IDLE;
          rise <= 1'b0;
          down <= 1'b0;
        end
      endcase
    end
  end

endmodule

