module top_module(
  clk, clk_ena, rst, 
  q);parameter ADDR_MOD = 9;
  parameter ADDR_WIDTH = 9;

  input clk, clk_ena, rst;
  output [ADDR_WIDTH-1:0] q;



  reg [ADDR_WIDTH-1:0] cnt;
  reg carry_tmp;

  always @ (posedge clk or posedge rst)
    begin
    if(rst)
      cnt <= 0;
    else if(clk_ena)
      if(carry_tmp)
    cnt <= 0;
   else
      cnt <= cnt + 1;  
  end

  always @ (cnt)
    begin
    if(cnt == ADDR_MOD-1)
      carry_tmp = 'b1;
    else 
      carry_tmp = 'b0;  
  end
  assign q = cnt;
endmodule

module top_module(
    input [3:0] D,
    input SHL,
    input SHR,
    input LOAD,
    input clk, // Added clk input
    output reg [3:0] Q
);reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(*) begin
    Q_next = Q_reg;
    if (LOAD) begin
        Q_next = D;
    end else if (SHL) begin
        Q_next = {Q_reg[2:0], 1'b0};
    end else if (SHR) begin
        Q_next = {1'b0, Q_reg[3:1]};
    end
end

always @(posedge clk) begin
    Q_reg <= Q_next;
end

assign Q = Q_reg;

endmodule

