module top_module(
  output reg [5:0] Q,
  input seq_clr,
  input seq_cnt_en,
  input slowest_sync_clk
);reg [5:0] q_int0;

  always @(*) begin
    q_int0[0] = Q[0];
    q_int0[1] = Q[0] & ~Q[1];
    q_int0[2] = (Q[0] & Q[1]) ^ Q[2];
    q_int0[3] = (Q[1] & ~Q[0]) | (Q[2] & Q[3]);
    q_int0[4] = (Q[2] & ~Q[0] & ~Q[1]) | (Q[3] & Q[4]);
    q_int0[5] = (Q[3] & Q[1]) | (Q[0] & Q[2]) | (Q[4] & Q[5]);
  end

  always @(posedge slowest_sync_clk) begin
    if (seq_clr) begin
      Q <= 6'h0;
    end else if (seq_cnt_en) begin
      Q <= q_int0;
    end
  end

endmodule

