    input k,
    input l,
    output y
);
    assign y = ~(k | l);
endmodule

module H(
    input k,
    input l,
    output y
);
    assign y = ~(k | l);
endmodule

module top_module(
    input k,
    input l,
    output y
);
    wire g_out, h_out;

    G g1(.k(k), .l(l), .y(g_out));
    H h1(.k(k), .l(l), .y(h_out));

