module top_module(
  input clock,
  input [31:0] data,
  input rdreq,
  input sclr,
  input wrreq,
  output reg empty,
  output reg full,
  output reg [31:0] q,
  output reg [4:0] usedw
);reg [31:0] mem [0:31];
  reg [4:0] head = 0;
  reg [4:0] tail = 0;
  reg [4:0] count = 0;

  always @(posedge clock) begin
    if (sclr) begin
      head <= 0;
      tail <= 0;
      count <= 0;
      empty <= 1;
      full <= 0;
      usedw <= 0;
      q <= 0;
    end else begin
      if (wrreq && !full) begin
        mem[head] <= data;
        head <= (head + 1) % 32;
        count <= count + 1;
        empty <= 0;
        if (count == 31) full <= 1; // Change from 32 to 31 for correct comparison
      end
      if (rdreq && !empty) begin
        q <= mem[tail];
        tail <= (tail + 1) % 32;
        count <= count - 1;
        full <= 0;
        if (count == 1) empty <= 1;
      end
      usedw <= count;
    end
  end

endmodule

module top_module(
  input [n*8-1:0] in,
  input [15:0] check,
  output reg error,
  output reg [15:0] out
);parameter n = 16; // number of input bytes

reg [15:0] A = 1;
reg [15:0] B = 1;

integer i;

always @(*) begin
  A = 1;
  B = 1;
  for (i = 0; i < n; i = i + 1) begin
    A = (A + in[i*8 +: 8]) % 65521;
    B = (B + A) % 65521;
  end
  out = (B << 16) | A;
end

always @(*) begin
  error = (out == check) ? 0 : 1;
end

endmodule

