module top_module(/*AUTOARG*/
   // Outputs
   output full, 
   output prog_full, 
   output [DW-1:0] dout, 
   output empty, 
   output valid,
   // Inputs
   input wr_rst, 
   input rd_rst, 
   input wr_clk, 
   input rd_clk, 
   input wr_en, 
   input [DW-1:0] din, 
   input rd_en
   );parameter DW    = 104;        //FIFO width
   parameter DEPTH = 16;          //FIFO depth

   reg [DW-1:0] fifo [DEPTH-1:0];
   reg [4:0] wr_ptr;
   reg [4:0] rd_ptr;
   wire [4:0] fifo_count;
   reg [DW-1:0] dout_reg; // Register to hold dout value

   assign full = (fifo_count == DEPTH);
   assign prog_full = (fifo_count >= DEPTH-4);
   assign empty = (fifo_count == 0);
   assign valid = (fifo_count > 0);
   assign dout = dout_reg; // Assign dout_reg to dout

   always @(posedge wr_clk or negedge wr_rst) begin
      if(!wr_rst) begin
         wr_ptr <= 0;
      end else if(wr_en && !full) begin
         fifo[wr_ptr] <= din;
         wr_ptr <= wr_ptr + 1;
      end
   end

   always @(posedge rd_clk or negedge rd_rst) begin
      if(!rd_rst) begin
         rd_ptr <= 0;
         dout_reg <= 0; // Initialize dout_reg
      end else if(rd_en && !empty) begin
         dout_reg <= fifo[rd_ptr];
         rd_ptr <= rd_ptr + 1;
      end
   end

   assign fifo_count = wr_ptr - rd_ptr;

endmodule

