description:
Design a circuit that transforms 4-bit input data into a 3-bit output based on a specific condition. If the input data is 8 or greater, the least significant three bits of the input (data_in[2:0]) are output as data_out, and the valid signal is set high. If the input data is less than 8, the valid signal is set low and the output remains unchanged. This module essentially acts as a conditional data filter and output generator, indicating the validity of the output based on the input's magnitude.
module top_module(/*AUTOARG*/
   // Inputs
   clk,
   data_in,

   // Outputs
   data_out,
   valid
   );

code:
module top_module(/*AUTOARG*/
   // Inputs
   clk,
   data_in,

   // Outputs
   data_out,
   valid
   );input clk;
   input [3:0] data_in;
   output [2:0] data_out;
   output valid;

   reg [2:0] data_out_reg;
   reg valid_reg;

   always @(posedge clk) begin
      if (data_in >= 8) begin
         data_out_reg <= data_in[2:0];
         valid_reg <= 1;
      end else begin
         valid_reg <= 0;
      end
   end

   assign data_out = data_out_reg;
   assign valid = valid_reg;

endmodule

