module top_module(
    input up_down,
    input reset,
    input count_up_clk,
    input count_down_clk,
    input [3:0] A,
    input [3:0] B,
    output reg [7:0] Y
);reg [3:0] count_reg;
reg [3:0] A_reg;
reg [3:0] B_reg;
reg [2:0] booth_reg;

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        count_reg <= 4'b0000;
        A_reg <= A;
        B_reg <= B;
        booth_reg <= 3'b000;
    end else begin
        if (up_down) begin
            count_reg <= count_reg + 1;
        end else begin
            count_reg <= count_reg - 1;
        end
    end
end

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        Y <= 8'b00000000;
    end else begin
        if (booth_reg == 3'b000) begin
            Y <= {1'b0, Y[7:1]};
        end else if (booth_reg == 3'b001 || booth_reg == 3'b111) begin
            Y <= Y + (A_reg << 4);
        end else if (booth_reg == 3'b010 || booth_reg == 3'b110) begin
            Y <= Y + (A_reg << 3);
        end else if (booth_reg == 3'b100 || booth_reg == 3'b101) begin
            Y <= Y + (A_reg << 2);
        end
    end
end

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        booth_reg <= 3'b000;
    end else begin
        if (up_down) begin
            if (count_reg == 4'b1000) begin
                booth_reg <= booth_reg + 1;
            end
        end else begin
            if (count_reg == 4'b0000) begin
                booth_reg <= booth_reg - 1;
            end
        end
    end
end

always @(posedge count_up_clk or posedge count_down_clk) begin
    if (reset) begin
        A_reg <= A;
        B_reg <= B;
    end else begin
        if (up_down) begin
            A_reg <= {A_reg[2:0], A_reg[3]};
            B_reg <= {B_reg[2:0], B_reg[3]};
        end else begin
            A_reg <= {A_reg[3], A_reg[2:0]};
            B_reg <= {B_reg[3], B_reg[2:0]};
        end
    end
end

endmodule

module top_module(
    A   ,
    B   ,
    SEL ,
    OUT
);// Module ports
    input  A   ;
    input  B   ;
    input  SEL ;
    output OUT ;

    // Local signals
    wire  not_SEL;
    wire  A_and_not_SEL;
    wire  B_and_SEL;

    // Invert SEL signal
    not not_SEL_inst (not_SEL, SEL);

    // AND A and not_SEL
    and A_and_not_SEL_inst (A_and_not_SEL, A, not_SEL);

    // AND B and SEL
    and B_and_SEL_inst (B_and_SEL, B, SEL);

    // OR the two AND gates
    or or_inst (OUT, A_and_not_SEL, B_and_SEL);

endmodule

