description:
Implement the Verilog module based on the following description.
Module R implements the boolean function z = (x & ~y).

// Module S can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 0.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two R submodules and two S submodules. The first input of all four submodules is connect to input 't', and the second input of all four submodules is connected to 'u'. The output of the first R submodule is connected to a two-input OR gate, along with the output of the first S submodule. The second pair of R and S submodules is similarly connected to an AND gate. The output of the OR and the AND is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input t,
    input u,
    output z);

code:
module R(
    input t,
    input u,
    output z
);
    assign z = (t & ~u);
endmodule

module S(
    input t,
    input u,
    output z
);
    assign z = (t & ~u);
endmodule

module top_module(
    input t,
    input u,
    output z
);
    wire r1_out, r2_out, s1_out, s2_out;
    wire or_out, and_out;

    R r1(.t(t), .u(u), .z(r1_out));
    R r2(.t(t), .u(u), .z(r2_out));
    S s1(.t(t), .u(u), .z(s1_out));
    S s2(.t(t), .u(u), .z(s2_out));

    assign or_out = r1_out | s1_out;
    assign and_out = r2_out & s2_out;

    assign z = or_out ^ and_out;
endmodule

