    reg muxwre;
    always @(*)
        case (WREMUX)
            "1": muxwre = 1'b1;
            "0": muxwre = 1'b0;
            "INV": muxwre = ~WRE;
            default: muxwre = WRE;
        endcase


    always @(posedge muxwck)
        if (muxwre)
            mem[{WAD3, WAD2, WAD1, WAD0}] <= {DI1, DI0};

    assign {DO1, DO0} = mem[{RAD3, RAD2, RAD1, RAD0}];

endmodule

