module fsm (
    input clk,
    input reset,
    input h,
    output reg u);

    parameter START=0, STAGE1=1, STAGE2=2, STAGE3=3, STAGE4=4;
    reg [2:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= START;
        else state <= next;
    end

    always_comb begin
        case (state)
            START: next = h ? STAGE1 : START;
            STAGE1: next = h ? STAGE1 : STAGE2;
            STAGE2: next = h ? STAGE1 : STAGE3;
            STAGE3: next = h ? STAGE1 : STAGE4;
            STAGE4: next = h ? STAGE1 : START;
            default: next = 'x;
        endcase
    end

    assign u = (state == STAGE4);

endmodule

