module top_module(s, cout, i1, i2, c0);output [3:0] s;   // Change to a 4-bit output
    output cout; 
    input [3:0] i1;   // Change to a 4-bit input
    input [3:0] i2;   // Change to a 4-bit input
    input c0; 

    wire [3:0] g; 
    wire [3:0] p; 
    wire [3:1] c; 

    assign g[3:0] = i1[3:0] & i2[3:0]; 
    assign p[3:0] = i1[3:0] ^ i2[3:0]; 
    assign c[1] = g[0] | (p[0] & c0); 
    assign c[2] = g[1] | (g[0] & p[1]) | (p[0] & p[1] & c0); 
    assign c[3] = g[2] | (g[1] & p[2]) | (g[0] & p[1] & p[2]) | (p[0] & p[1] & p[2] & c0); 
    assign cout = g[3] | (g[2] & p[3]) | (g[1] & p[2] & p[3]) | (g[0] & p[1] & p[2] & p[3]) | (p[0] & p[1] & p[2] & p[3] & c0); 
    assign s[0] = p[0] ^ c0; 
    assign s[3:1] = p[3:1] ^ c[3:1]; 
endmodule

