description:
Design a Moore state machine that detects a specific sequence of input bits. The detector has four states (S0, S1, S2, S3) and transitions between them based on the current state and the input signal x. The output y is asserted high (1) only when the machine is in state S3, indicating that the desired sequence has been detected. The system also includes a reset functionality to return to the initial state S0.
module top_module(
	output reg y,
	input x, clock, reset
    );

code:
module top_module(
	output reg y,
	input x, clock, reset
    );reg [1:0] state, next_state;
	parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

	always @ (posedge clock, negedge reset)
	if (reset == 0) state <= S0;
	else state <= next_state;

	always @ (state, x)
		case (state)
			S0: if (x) next_state = S1; else next_state = S0;
			S1: if (x) next_state = S2; else next_state = S0;
			S2: if (x) next_state = S3; else next_state = S0;
			S3: if (x) next_state = S3; else next_state = S0;
		endcase

	always @ (state, x)
		case (state)
			S0, S1, S2: y = 0;
			S3: y = 1;
		endcase

endmodule

