module top_module(A, B, reset, clk, sum, carry);input [3:0] A;
   input [3:0] B;
   input reset;
   input clk;
   output [3:0] sum;
   output carry;

   reg [3:0] sum_reg;
   reg carry_reg;

   always @(posedge clk) begin
      if (reset) begin
         sum_reg <= 4'b0;
         carry_reg <= 1'b0;
      end
      else begin
         sum_reg <= A + B;
         carry_reg <= (A[3] & B[3]) | (A[3] & ~sum_reg[3]) | (B[3] & ~sum_reg[3]);
      end
   end

   assign sum = sum_reg;
   assign carry = carry_reg;

endmodule

module top_module(
    input clk,
    input rst_n,
    input data_in,
    output data_out
);localparam IDLE = 2'd0; 
localparam S0 = 2'd1; 
localparam S1 = 2'd2; 
localparam S2 = 2'd3; 
reg [1:0] c_state;
reg [1:0] n_state;


always @(posedge clk or negedge rst_n) begin
   if(~rst_n) begin
       c_state <= IDLE;
   end 
   else begin
       c_state <= n_state;
   end
end

always @(*) begin
   case(c_state) 
   IDLE: n_state = data_in ? S1 : S0;
   S0: n_state = data_in ? S1 : S0;
   S1: n_state = data_in ? S0 : S2;
   S2: n_state = data_in ? S2 : S1;
   default: n_state = IDLE;
   endcase
end

assign data_out = c_state == S0;
endmodule

