`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (combinational circuit)
    reg [3:0] in;
    wire [7:0] final_output;
    wire out_and;
    wire out_or;
    wire out_xor;
    wire [1:0] pos;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .in(in),
        .final_output(final_output),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor),
        .pos(pos)
    );
    task verify_logic;

        input [3:0] val;
        reg e_and, e_or, e_xor;
        reg [1:0] e_pos;
        reg [7:0] e_final;
        begin
            in = val;


            e_and = &val;
            e_or  = |val;
            e_xor = ^val;


            if (val[3])      e_pos = 2'd3;
            else if (val[2]) e_pos = 2'd2;
            else if (val[1]) e_pos = 2'd1;
            else             e_pos = 2'd0;



            e_final = {~val, val};

            #10;
            #1;

            check_outputs(e_final, e_and, e_or, e_xor, e_pos);
        end
        endtask

    task testcase001;

        begin
            $display("Test Case 001: Input 0000 (All Zeros)");
            verify_logic(4'b0000);
        end
        endtask

    task testcase002;

        begin
            $display("Test Case 002: Input 1111 (All Ones)");
            verify_logic(4'b1111);
        end
        endtask

    task testcase003;

        begin
            $display("Test Case 003: Input 0001");
            verify_logic(4'b0001);
        end
        endtask

    task testcase004;

        begin
            $display("Test Case 004: Input 0010");
            verify_logic(4'b0010);
