      4'b1110: o_signal = 2'b01;
      4'b1111: o_signal = 2'b10;
      default:  o_signal = 2'b00; //default value for undefined inputs
    endcase
  end

endmodule

testbench:
`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (combinational circuit)
    reg [3:0] i_signal;
    wire [1:0] o_signal;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .i_signal(i_signal),
        .o_signal(o_signal)
    );
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Mapping Input 4'h0", test_num);
        i_signal = 4'h0;
        #1;

        check_outputs(2'b00);
    end
        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Mapping Input 4'h1 (Same Group)", test_num);
        i_signal = 4'h1;
        #1;

        check_outputs(2'b00);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Mapping Input 4'h2", test_num);
        i_signal = 4'h2;
        #1;

        check_outputs(2'b01);
    end
        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Mapping Input 4'h4", test_num);
        i_signal = 4'h4;
        #1;

        check_outputs(2'b10);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Testing Default Case (Input 4'hF)", test_num);
        i_signal = 4'hF;
        #1;

        check_outputs(2'b11);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Testing Default Case (Input 4'h8)", test_num);
        i_signal = 4'h8;
        #1;

        check_outputs(2'b11);
    end
        endtask

    task testcase007;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Testing Input 4'b1010", test_num);
        i_signal = 4'b1010;
        #1;

        check_outputs(2'b11);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [1:0] expected_o_signal;
        begin
            #1; // Small delay for combinational logic to settle
            if (expected_o_signal === (expected_o_signal ^ o_signal ^ expected_o_signal)) begin
                $display("PASS");
                $display("  Outputs: o_signal=%h",
                         o_signal);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: o_signal=%h",
                         expected_o_signal);
                $display("  Got:      o_signal=%h",
                         o_signal);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

endmodule
